import{_ as i,o as l,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-11-26 -- Ceph Testing Meeting","description":"","frontmatter":{"title":"2019-11-26 -- Ceph Testing Meeting","date":"2019-11-26T00:00:00.000Z","updated":"2019-11-28T00:00:00.000Z","tags":["Ceph","分布式存储","测试","CRUSH 算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-26_-_-_Ceph_Testing_Meeting.md","filePath":"posts/2019/2019-11-26_-_-_Ceph_Testing_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-11-26_-_-_Ceph_Testing_Meeting.md"};function r(o,t,p,_,a,g){return l(),e("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 2019年11月26日</p><p><strong>参会人员：</strong> Yuri, Bruno, Greg 以及其他未提及名字的成员</p><p><strong>会议议题：</strong></p><ol><li><p><strong>假期安排</strong>：</p><ul><li>Yuri提到他们在美国有较长的圣诞假期。</li><li>讨论了新年假期的安排。</li></ul></li><li><p><strong>Ceph项目更新</strong>：</p><ul><li>最近有几个PR（Pull Request）被合并到Ceph的master分支，目前没有发现问题。</li><li>讨论了在drop目录下的远程目录是否发生变化，确认没有变化。</li><li>讨论了Nautilus 14版本的工作进展，预计很快可以发布。</li></ul></li><li><p><strong>技术问题讨论</strong>：</p><ul><li>Greg提到了一些旧的PR，特别是关于过滤选项的问题，发现inspect选项的过滤逻辑与预期不符。</li><li>讨论了如何处理这些技术问题，包括关闭当前PR并创建新的PR。</li></ul></li><li><p><strong>其他事项</strong>：</p><ul><li>提到了一个关于添加过滤选项的新的ticket（编号1366），需要进一步审查。</li><li>讨论了关于部署过程的测试和细节。</li></ul></li></ol><p><strong>决定事项：</strong></p><ul><li>确认远程目录在drop目录下没有变化。</li><li>决定关闭当前的PR并创建新的PR来解决过滤选项的问题。</li><li>需要审查并处理ticket 1366。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>Greg将关闭当前的PR并创建新的PR。</li><li>需要审查并处理ticket 1366。</li><li>继续推进Nautilus 14版本的发布工作。</li></ul><p><strong>其他备注：</strong></p><ul><li>会议中提到了假期安排和个人旅行计划。</li><li>提醒团队成员在假期期间保持联系。</li></ul><p><strong>会议结束：</strong></p><ul><li>会议在讨论完所有议题后结束，祝大家假期愉快。</li></ul><p>本次会议纪要准确反映了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。在技术问题讨论部分，原始字幕中的一些信息未能准确传达，如关于filter选项和inspect选项的讨论。改进后的总结中已添加了这些内容。</p>',14)])])}const c=i(n,[["render",r]]);export{d as __pageData,c as default};
